(5206900, 757424, 75192, '<td valign="top">She is naturally beautiful - a great shot. Love her freckles!</td>', 'She is naturally beautiful - a great shot. Love her freckles!', '2009-01-20 14:26:02.000000', NULL, 1),
(5206904, 757480, 75192, '<td valign="top">Cute smile!</td>', 'Cute smile!', '2009-01-20 14:27:21.000000', NULL, 1),
(5206909, 756085, 75192, '<td valign="top">Wow, a ribbon winner I think. Gorgeous big brown eyes - great picture.</td>', 'Wow, a ribbon winner I think. Gorgeous big brown eyes - great picture.', '2009-01-20 14:28:47.000000', NULL, 1),
(5206912, 757665, 102542, '<td valign="top">This one made me smile</td>', 'This one made me smile', '2009-01-20 14:29:28.000000', NULL, 1),
(5206913, 757520, 63218, '<td valign="top">character &amp; personality too!</td>', 'character & personality too!', '2009-01-20 14:29:35.000000', NULL, 1),
(5206917, 757554, 75192, '<td valign="top">What delicate features she has - traditionally beautiful a la Audrey Hepburn.</td>', 'What delicate features she has - traditionally beautiful a la Audrey Hepburn.', '2009-01-20 14:30:28.000000', NULL, 1),
(5206919, 757543, 75192, '<td valign="top">Wow, very handsome. Reminds me a bit of Sean Connery. A wonderful expression on his face. Kind eyes.</td>', 'Wow, very handsome. Reminds me a bit of Sean Connery. A wonderful expression on his face. Kind eyes.', '2009-01-20 14:31:51.000000', NULL, 1),
(5206939, 757363, 88204, '<td valign="top">Great subject. Eye contact and moving the subject off center would have made it a stronger composition.</td>', 'Great subject. Eye contact and moving the subject off center would have made it a stronger composition.', '2009-01-20 14:38:47.000000', NULL, 1),
(5206940, 757450, 88204, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2009-01-20 14:39:54.000000', NULL, 1),
(5206942, 756781, 88204, '<td valign="top">Nice side lighting.</td>', 'Nice side lighting.', '2009-01-20 14:40:26.000000', NULL, 1),
(5206943, 757538, 88204, '<td valign="top">Nice eyes. I wish we could see the mouth to complete the expression.</td>', 'Nice eyes. I wish we could see the mouth to complete the expression.', '2009-01-20 14:40:47.000000', NULL, 1),
(5206946, 757474, 88204, '<td valign="top">Very nice even lighting. Nice position and expression. The post processing looks a little strong in the skin and eyes.</td>', 'Very nice even lighting. Nice position and expression. The post processing looks a little strong in the skin and eyes.', '2009-01-20 14:41:46.000000', NULL, 1),
(5206947, 757686, 88204, '<td valign="top">Wonderful focus on the eye. I like the mystery of the scarf.</td>', 'Wonderful focus on the eye. I like the mystery of the scarf.', '2009-01-20 14:42:35.000000', NULL, 1),
(5206952, 757203, 88204, '<td valign="top">Definitely shows a flirtatious personality. Nice composition, angle and pose. Backlighting works great. Attractive models doesn''t hurt either!</td>', 'Definitely shows a flirtatious personality. Nice composition, angle and pose. Backlighting works great. Attractive models doesn''t hurt either!', '2009-01-20 14:43:33.000000', NULL, 1),
(5206955, 756457, 88204, '<td valign="top">Great composition and expression. I like the shallow DoF. I''m not sure what "mirthful" means but I love the shot and will assume it has something to do with a charming little cherub.</td>', 'Great composition and expression. I like the shallow DoF. I''m not sure what "mirthful" means but I love the shot and will assume it has something to do with a charming little cherub.', '2009-01-20 14:44:39.000000', NULL, 1),
(5206980, 757789, 88204, '<td valign="top">Definitely looks loud! The arms up in the air is a great touch. You show just enough to get the point across without losing detail and focus on the face. Blue is a nice loud color to emphasize the point. Great sharp focus and even lighting.</td>', 'Definitely looks loud! The arms up in the air is a great touch. You show just enough to get the point across without losing detail and focus on the face. Blue is a nice loud color to emphasize the point. Great sharp focus and even lighting.', '2009-01-20 14:57:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5206987, 756913, 88204, '<td valign="top">He doesn''t look one bit friendly!  :)<br/>Nice even lighting and shallow DoF. I assume the noise is intentional.</td>', 'He doesn''t look one bit friendly!  :)Nice even lighting and shallow DoF. I assume the noise is intentional.', '2009-01-20 14:58:43.000000', NULL, 1),
(5206988, 757659, 49788, '<td valign="top">Here are my thoughts on this photo: <br/>* The guy''s expression and the hand to the face capture "day dreaming" really well. Nice.<br/>* I like the foreground elements. Gives the photo a nice depth. <br/>* Focus was one thing I was reacting negatively to. The guy''s head appears slightly out of focus. Rosie O''Donnell looks to me like the sharpest thing in the photo, which I found a bit distracting. Overall the the guy, the main subject, just lacks the sharpness I''m used to seeing in some of the photos here.<br/>* The heads in the upper right kept pulling my eye up there. This effect for me was exacerbated the fact that it''s the brightest part of the image. It also seems like there''s another face shape in the right foreground. So my eye kind of darts there as well.<br/>* There''s generally a lot going on in the image: the faces, the text, the sharp diagonal of the railing.</td>', 'Here are my thoughts on this photo: * The guy''s expression and the hand to the face capture "day dreaming" really well. Nice.* I like the foreground elements. Gives the photo a nice depth. * Focus was one thing I was reacting negatively to. The guy''s head appears slightly out of focus. Rosie O''Donnell looks to me like the sharpest thing in the photo, which I found a bit distracting. Overall the the guy, the main subject, just lacks the sharpness I''m used to seeing in some of the photos here.* The heads in the upper right kept pulling my eye up there. This effect for me was exacerbated the fact that it''s the brightest part of the image. It also seems like there''s another face shape in the right foreground. So my eye kind of darts there as well.* There''s generally a lot going on in the image: the faces, the text, the sharp diagonal of the railing.', '2009-01-20 14:58:57.000000', NULL, 1),
(5206990, 757053, 88204, '<td valign="top">I don''t get the title but I love the shot. I would have titled it silly or playful or wild child or something. Great use of B&amp;W, great expression. My favorite so far.</td>', 'I don''t get the title but I love the shot. I would have titled it silly or playful or wild child or something. Great use of B&W, great expression. My favorite so far.', '2009-01-20 15:00:25.000000', NULL, 1),
(5206992, 757844, 88204, '<td valign="top">Great expression and title to go with it.</td>', 'Great expression and title to go with it.', '2009-01-20 15:00:49.000000', NULL, 1),
(5206997, 755680, 88204, '<td valign="top">Great expression and title. Wonderful eyes!</td>', 'Great expression and title. Wonderful eyes!', '2009-01-20 15:02:03.000000', NULL, 1),
(5206998, 757247, 49788, '<td valign="top">* Some noise problems.<br/>* I wish I could see one of their faces<br/>* The big mass of black doesn''t really do it for me. Seems like that part of the image is a silhouette, but the other part is "real". Kind of confusing.</td>', '* Some noise problems.* I wish I could see one of their faces* The big mass of black doesn''t really do it for me. Seems like that part of the image is a silhouette, but the other part is "real". Kind of confusing.', '2009-01-20 15:02:04.000000', NULL, 1),
(5207000, 757907, 49788, '<td valign="top">* Not sure what this reveals about this person''s personality.<br/>* Kind of flat lighting<br/>* White balance makes the subject very yellow</td>', '* Not sure what this reveals about this person''s personality.* Kind of flat lighting* White balance makes the subject very yellow', '2009-01-20 15:03:09.000000', NULL, 1),
(5207001, 755597, 49788, '<td valign="top">Looks like overdone sharpening. Kind of ruins the image for me.</td>', 'Looks like overdone sharpening. Kind of ruins the image for me.', '2009-01-20 15:04:04.000000', NULL, 1),
(5207002, 757584, 49788, '<td valign="top">Find the foreground elements kind of distracting. There''s a big patch of black where her back is; lighting could be softer.</td>', 'Find the foreground elements kind of distracting. There''s a big patch of black where her back is; lighting could be softer.', '2009-01-20 15:04:41.000000', NULL, 1),
(5207007, 757363, 49788, '<td valign="top">* Composition is a bit static with her face in the middle.<br/>* Lighting is a bit flat -- would be better with stronger directional lighting from the side<br/>*</td>', '* Composition is a bit static with her face in the middle.* Lighting is a bit flat -- would be better with stronger directional lighting from the side*', '2009-01-20 15:05:34.000000', NULL, 1),
(5207011, 757290, 49788, '<td valign="top">That is a lot of cameras. :)<br/> <br/>Don''t get that strong a sense for this guy''s personality though. King of cameras? Why aren''t the others envying his cameras?</td>', 'That is a lot of cameras. :) Don''t get that strong a sense for this guy''s personality though. King of cameras? Why aren''t the others envying his cameras?', '2009-01-20 15:06:22.000000', NULL, 1),
(5207014, 756262, 49788, '<td valign="top">Some focusing problems it looks like (could be a lot sharper around the eyes and eyebrows), and I''m not sure what this says about his personality. He likes to laugh?</td>', 'Some focusing problems it looks like (could be a lot sharper around the eyes and eyebrows), and I''m not sure what this says about his personality. He likes to laugh?', '2009-01-20 15:07:16.000000', NULL, 1),
(5207016, 757474, 49788, '<td valign="top">Looks overprocessed to me...</td>', 'Looks overprocessed to me...', '2009-01-20 15:07:41.000000', NULL, 1),
(5207017, 757108, 49788, '<td valign="top">Not sure what this says about her personality. I wish that she, and not her hands, were in focus.</td>', 'Not sure what this says about her personality. I wish that she, and not her hands, were in focus.', '2009-01-20 15:08:02.000000', NULL, 1),
(5207024, 757304, 49788, '<td valign="top">Too much going on in the photo, I would say. Not sure what I''m supposed to take away about his personality, either.</td>', 'Too much going on in the photo, I would say. Not sure what I''m supposed to take away about his personality, either.', '2009-01-20 15:09:05.000000', NULL, 1),
(5207025, 755931, 49788, '<td valign="top">Don''t think this tells me much about his personality (he doesn''t look evil); not sure I like the blue effect. And his beard, rather than his eyes, are in focus.</td>', 'Don''t think this tells me much about his personality (he doesn''t look evil); not sure I like the blue effect. And his beard, rather than his eyes, are in focus.', '2009-01-20 15:09:20.000000', NULL, 1),
(5207027, 757310, 49788, '<td valign="top">I don''t really care for the strange use of photoshop to color certain parts of the image. Bad composite, it looks like, too, but maybe that''s just the flash.</td>', 'I don''t really care for the strange use of photoshop to color certain parts of the image. Bad composite, it looks like, too, but maybe that''s just the flash.', '2009-01-20 15:09:40.000000', NULL, 1),
(5207031, 756085, 49788, '<td valign="top">Really nice, crisp focus on the eyes. Beautiful lighting. Very cute kid. Shows curiosity very clearly. Nice crop. Love the image.</td>', 'Really nice, crisp focus on the eyes. Beautiful lighting. Very cute kid. Shows curiosity very clearly. Nice crop. Love the image.', '2009-01-20 15:10:30.000000', NULL, 1),
(5207100, 757507, 92577, '<td valign="top">a light behind him might make it punchier - good luck</td>', 'a light behind him might make it punchier - good luck', '2009-01-20 15:46:55.000000', NULL, 1),
(5207106, 757545, 92577, '<td valign="top">curious (and incongruous) setting. otherwise good</td>', 'curious (and incongruous) setting. otherwise good', '2009-01-20 15:49:31.000000', NULL, 1),
(5207118, 757569, 92577, '<td valign="top">why, oh why didn''t you crop those floorboards? And then make a levels or curves adjustment to boost the contrast? <br/>Other than that it''s great - good luck</td>', 'why, oh why didn''t you crop those floorboards? And then make a levels or curves adjustment to boost the contrast? Other than that it''s great - good luck', '2009-01-20 15:53:36.000000', NULL, 1),
(5207127, 756085, 92577, '<td valign="top">Hello again. She''s beautiful and a great model but it looks as if she''s been chewing her nail varnish this time :¬)</td>', 'Hello again. She''s beautiful and a great model but it looks as if she''s been chewing her nail varnish this time :¬)', '2009-01-20 15:58:16.000000', NULL, 1),
(5207184, 755680, 15711, '<td valign="top">Oh this is just fabulous, including that little tumb.  Terrific eyes and lighting. I like this a lot.  If I were to tweak anything, I might''ve done something with the arm of the chair to the left, but no big deal.</td>', 'Oh this is just fabulous, including that little tumb.  Terrific eyes and lighting. I like this a lot.  If I were to tweak anything, I might''ve done something with the arm of the chair to the left, but no big deal.', '2009-01-20 16:18:43.000000', NULL, 1),
(5207188, 757639, 15711, '<td valign="top">How much fun.  Now you get to spend the next 2 months telling her, "no, that was only for that one time. " LOL  Love it.</td>', 'How much fun.  Now you get to spend the next 2 months telling her, "no, that was only for that one time. " LOL  Love it.', '2009-01-20 16:19:08.000000', NULL, 1),
(5207190, 757300, 15711, '<td valign="top">This is beautiful. I wish that white (chair?) weren''t behind her on the left.</td>', 'This is beautiful. I wish that white (chair?) weren''t behind her on the left.', '2009-01-20 16:19:49.000000', NULL, 1),
(5207195, 757128, 15711, '<td valign="top">Oh this is terrific.  Could''ve been in the other challenge for business attire.</td>', 'Oh this is terrific.  Could''ve been in the other challenge for business attire.', '2009-01-20 16:20:39.000000', NULL, 1),
(5207202, 757298, 15711, '<td valign="top">I almost have those same glasses.  This is darling with the red theme. Love the polka dots.</td>', 'I almost have those same glasses.  This is darling with the red theme. Love the polka dots.', '2009-01-20 16:23:44.000000', NULL, 1),
