(5207213, 757665, 15711, '<td valign="top">Love this.</td>', 'Love this.', '2009-01-20 16:28:07.000000', NULL, 1),
(5207214, 756085, 58415, '<td valign="top">very expressive eyes</td>', 'very expressive eyes', '2009-01-20 16:28:19.000000', NULL, 1),
(5207216, 757467, 15711, '<td valign="top">Just adorable. Love the touch of high key.</td>', 'Just adorable. Love the touch of high key.', '2009-01-20 16:29:28.000000', NULL, 1),
(5207250, 757290, 29011, '<td valign="top">Dean? You have a nice rack of digicams there ;) The darkening of the corners and composition indicate the focus is on photog(you, not lacking in personality) but the mix of personalities makes this shot for me. The lighting looks great.</td>', 'Dean? You have a nice rack of digicams there ;) The darkening of the corners and composition indicate the focus is on photog(you, not lacking in personality) but the mix of personalities makes this shot for me. The lighting looks great.', '2009-01-20 16:49:39.000000', NULL, 1),
(5207320, 757760, 92577, '<td valign="top">classic</td>', 'classic', '2009-01-20 17:22:53.000000', NULL, 1),
