(5211179, 756085, 73981, '<td valign="top">I saw this little fella over on photographers direct for the portrait inquiry.</td>', 'I saw this little fella over on photographers direct for the portrait inquiry.', '2009-01-22 02:35:22.000000', NULL, 1),
