(5211273, 757639, 88204, '<td valign="top">Wonderful shot! I''m curious to know how you did it. Great expression, lighting, simplicity and captured a unique moment... all which show an exuberant personality. Well done! 10</td>', 'Wonderful shot! I''m curious to know how you did it. Great expression, lighting, simplicity and captured a unique moment... all which show an exuberant personality. Well done! 10', '2009-01-22 06:31:44.000000', NULL, 1),
(5211865, 757738, 47470, '<td valign="top">Cut expression.  The white hair on her hat is a little distracting since it''s in focus.</td>', 'Cut expression.  The white hair on her hat is a little distracting since it''s in focus.', '2009-01-22 14:14:04.000000', NULL, 1),
(5211876, 757128, 47470, '<td valign="top">This is great.</td>', 'This is great.', '2009-01-22 14:16:56.000000', NULL, 1),
(5211905, 757448, 47470, '<td valign="top">I think this is a little dark.</td>', 'I think this is a little dark.', '2009-01-22 14:26:48.000000', NULL, 1),
(5211970, 756876, 47470, '<td valign="top">This is a very interesting photo because foreigners don''t often get to see Mumbai''s beach.  I''m not exactly sure what he''s doing with the thing in his hand, but I like this photo.</td>', 'This is a very interesting photo because foreigners don''t often get to see Mumbai''s beach.  I''m not exactly sure what he''s doing with the thing in his hand, but I like this photo.', '2009-01-22 14:49:24.000000', NULL, 1),
(5211973, 757559, 47470, '<td valign="top">I wish dad''s head wasn''t cut off!  Nice soft lighting, especially the hair light.</td>', 'I wish dad''s head wasn''t cut off!  Nice soft lighting, especially the hair light.', '2009-01-22 14:50:36.000000', NULL, 1),
(5211975, 757857, 47470, '<td valign="top">I''m not sure I would have recognized that as chocolate without the title.</td>', 'I''m not sure I would have recognized that as chocolate without the title.', '2009-01-22 14:51:16.000000', NULL, 1),
(5211983, 757789, 47470, '<td valign="top">Very in-your-face, and great shot for the challenge.  Title fits perfectly.</td>', 'Very in-your-face, and great shot for the challenge.  Title fits perfectly.', '2009-01-22 14:55:27.000000', NULL, 1),
(5211990, 757760, 47470, '<td valign="top">I think the text at the top is a bit distracting.  Maybe if you cropped the top and included more of the messy floor?</td>', 'I think the text at the top is a bit distracting.  Maybe if you cropped the top and included more of the messy floor?', '2009-01-22 15:00:19.000000', NULL, 1),
(5211993, 757569, 47470, '<td valign="top">I think I would like this better with the floor cropped out.</td>', 'I think I would like this better with the floor cropped out.', '2009-01-22 15:01:08.000000', NULL, 1),
(5212021, 755899, 47470, '<td valign="top">The black seems painted in or something, leaving a weird halo of fuzzy gray around his face.  Normally I''d prefer the eye in focus, but the title seems to fit better like this.</td>', 'The black seems painted in or something, leaving a weird halo of fuzzy gray around his face.  Normally I''d prefer the eye in focus, but the title seems to fit better like this.', '2009-01-22 15:08:12.000000', NULL, 1),
(5212022, 757194, 47470, '<td valign="top">I wish there was a bit more detail in the blacks.</td>', 'I wish there was a bit more detail in the blacks.', '2009-01-22 15:08:15.000000', NULL, 1),
(5212023, 756448, 47470, '<td valign="top">A reflector to bounce some light back on her face would brighten this up a bit.</td>', 'A reflector to bounce some light back on her face would brighten this up a bit.', '2009-01-22 15:08:18.000000', NULL, 1),
(5212024, 757090, 47470, '<td valign="top">A little sharpening would make pop.</td>', 'A little sharpening would make pop.', '2009-01-22 15:08:19.000000', NULL, 1),
(5212025, 757907, 47470, '<td valign="top">The skin looks a bit too orange-y.  I think that lighting him from underneath makes him look older by emphasizing the bags under his eyes.</td>', 'The skin looks a bit too orange-y.  I think that lighting him from underneath makes him look older by emphasizing the bags under his eyes.', '2009-01-22 15:08:21.000000', NULL, 1),
(5212031, 757247, 47470, '<td valign="top">There''s a lot of grain in this.  I wonder if you tried anything to minimize it?  A quick pass of an iron over the sheet in the background would have made this look even more professional.</td>', 'There''s a lot of grain in this.  I wonder if you tried anything to minimize it?  A quick pass of an iron over the sheet in the background would have made this look even more professional.', '2009-01-22 15:14:44.000000', NULL, 1),
(5212082, 757224, 47470, '<td valign="top">It looks to me like there is a slight cyan color cast, and I think that might make the eyes stand out less.</td>', 'It looks to me like there is a slight cyan color cast, and I think that might make the eyes stand out less.', '2009-01-22 15:42:35.000000', NULL, 1),
(5212087, 757304, 47470, '<td valign="top">The background is a little crowded for my taste.  A shallower depth of field might fix that.</td>', 'The background is a little crowded for my taste.  A shallower depth of field might fix that.', '2009-01-22 15:43:49.000000', NULL, 1),
(5212088, 757180, 47470, '<td valign="top">He''s got a great expression, but the thing in the upper left is a little distracting.</td>', 'He''s got a great expression, but the thing in the upper left is a little distracting.', '2009-01-22 15:44:26.000000', NULL, 1),
(5212092, 757474, 47470, '<td valign="top">I think the crop is a bit tight on the bottom.</td>', 'I think the crop is a bit tight on the bottom.', '2009-01-22 15:46:59.000000', NULL, 1),
(5212107, 757545, 47470, '<td valign="top">I like the simplicity of the pose and the background, but blowing out the windows a bit more might add to the overall simplicity.</td>', 'I like the simplicity of the pose and the background, but blowing out the windows a bit more might add to the overall simplicity.', '2009-01-22 15:57:23.000000', NULL, 1),
(5212109, 756799, 47470, '<td valign="top">I wish I could see his face too.</td>', 'I wish I could see his face too.', '2009-01-22 15:57:53.000000', NULL, 1),
(5212117, 757286, 47470, '<td valign="top">The tilt seems too extreme to convey relaxation to me.  I think tilting an image gives edginess.</td>', 'The tilt seems too extreme to convey relaxation to me.  I think tilting an image gives edginess.', '2009-01-22 16:00:25.000000', NULL, 1),
(5212448, 757611, 48389, '<td valign="top">Man this face gets around almost as much as that other old g*t I know on here ;o) Very clever and made me chuckle :o)</td>', 'Man this face gets around almost as much as that other old g*t I know on here ;o) Very clever and made me chuckle :o)', '2009-01-22 18:40:10.000000', NULL, 1),
(5212455, 757303, 48389, '<td valign="top">Well, he looks great for his age :o) Nice composition, I like the position of the ''model'' in the frame. If it was my shot I''d have cropped the tiny git of detail on his t-shirt at the bottom of the frame out and possibly tried to get rid of the yellow sticker underneath his hand (some how) as they are a little distrcting...but then again I am very picky! ;o)</td>', 'Well, he looks great for his age :o) Nice composition, I like the position of the ''model'' in the frame. If it was my shot I''d have cropped the tiny git of detail on his t-shirt at the bottom of the frame out and possibly tried to get rid of the yellow sticker underneath his hand (some how) as they are a little distrcting...but then again I am very picky! ;o)', '2009-01-22 18:44:54.000000', NULL, 1),
(5212985, 757466, 76335, '<td valign="top">Yep. Wouldn''t mess with her on the schoolyard. Nicely composed, great personality.</td>', 'Yep. Wouldn''t mess with her on the schoolyard. Nicely composed, great personality.', '2009-01-22 21:55:22.000000', NULL, 1),
(5212994, 757665, 76335, '<td valign="top">Curiosity has more to do with nature than nurture -- at least at this age. Still an excellent capture.</td>', 'Curiosity has more to do with nature than nurture -- at least at this age. Still an excellent capture.', '2009-01-22 21:57:47.000000', NULL, 1),
(5213015, 755899, 76335, '<td valign="top">That''s rather frightening. Good use of the frame.</td>', 'That''s rather frightening. Good use of the frame.', '2009-01-22 22:01:42.000000', NULL, 1),
(5213016, 757738, 76335, '<td valign="top">Great expression, technically a bit flat.</td>', 'Great expression, technically a bit flat.', '2009-01-22 22:02:04.000000', NULL, 1),
(5213018, 757568, 76335, '<td valign="top">The title nails it! Candid? Nicely done.</td>', 'The title nails it! Candid? Nicely done.', '2009-01-22 22:02:35.000000', NULL, 1),
(5213022, 757605, 76335, '<td valign="top">Lensbaby? If so, I think it''s overprocessed. The fuzzy, funny background actually pulls attention from your subject. Otherwise, great personality, colors, composition.</td>', 'Lensbaby? If so, I think it''s overprocessed. The fuzzy, funny background actually pulls attention from your subject. Otherwise, great personality, colors, composition.', '2009-01-22 22:03:51.000000', NULL, 1),
(5213029, 757543, 76335, '<td valign="top">Good, warm, honest capture. Doesn''t look unnatural, and provides a real window to the soul.</td>', 'Good, warm, honest capture. Doesn''t look unnatural, and provides a real window to the soul.', '2009-01-22 22:06:36.000000', NULL, 1),
(5213032, 757053, 76335, '<td valign="top">Okay, I''ll buy it. To even pose for this, she must have a wonderful and carefree personality.</td>', 'Okay, I''ll buy it. To even pose for this, she must have a wonderful and carefree personality.', '2009-01-22 22:07:22.000000', NULL, 1),
(5213034, 757409, 76335, '<td valign="top">Great expression. She clearly has a lot on her mind, aspirations...</td>', 'Great expression. She clearly has a lot on her mind, aspirations...', '2009-01-22 22:07:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5213143, 757557, 66384, '<td valign="top">Although I really dislike the subject, I think this is an excellent photo and very appropriate for the challenge.</td>', 'Although I really dislike the subject, I think this is an excellent photo and very appropriate for the challenge.', '2009-01-22 22:45:45.000000', NULL, 1),
(5213162, 757094, 66384, '<td valign="top">I know this person. She is such a good sport. But I don''t think that is the personality you are trying to depict. ;) BTW, I love the chair.</td>', 'I know this person. She is such a good sport. But I don''t think that is the personality you are trying to depict. ;) BTW, I love the chair.', '2009-01-22 22:50:05.000000', NULL, 1),
(5213517, 756967, 33672, '<td valign="top">Very nice work. interesting with nice tones.</td>', 'Very nice work. interesting with nice tones.', '2009-01-23 00:19:29.000000', NULL, 1),
(5214042, 757665, 102999, '<td valign="top">Great shot. The expressions are captured really well. And the thing I liked the most is that the title is PERFECT :)</td>', 'Great shot. The expressions are captured really well. And the thing I liked the most is that the title is PERFECT :)', '2009-01-23 07:27:04.000000', NULL, 1),
