(5214053, 757757, 77192, '<td valign="top">The lightness of what''s immediately behind her seems to distract my attention from her face :-(</td>', 'The lightness of what''s immediately behind her seems to distract my attention from her face :-(', '2009-01-23 07:37:31.000000', NULL, 1),
(5214055, 757844, 77192, '<td valign="top">lol great expression.</td>', 'lol great expression.', '2009-01-23 07:38:11.000000', NULL, 1),
(5214057, 757687, 77192, '<td valign="top">like the crop and the black space around him.</td>', 'like the crop and the black space around him.', '2009-01-23 07:38:45.000000', NULL, 1),
(5214060, 757620, 77192, '<td valign="top">I must admit I wouldn''t have a clue what this has to do with personality apart from your title, and even then it''s a bit of a leap in the brain.</td>', 'I must admit I wouldn''t have a clue what this has to do with personality apart from your title, and even then it''s a bit of a leap in the brain.', '2009-01-23 07:41:23.000000', NULL, 1),
