(5218572, 756085, 76335, '<td valign="top">She seems thoughtful more than curious. Challenge aside, it''s a beautiful portrait.<br/><br/><i>Message edited by author 2009-01-26 11:46:07.</i></td>', 'She seems thoughtful more than curious. Challenge aside, it''s a beautiful portrait.', '2009-01-25 20:15:01.000000', '2009-01-26 11:46:07.000000', 1),
(5218583, 757507, 23053, '<td valign="top">I''ve voted on 62% of the photos so far and this is one of the few photos I''ve seen that actually meets the intent of the challenge, other than just shoe-horning some random portrait.  That being said, good luck with your photo.  So, you''ve got numerous books about the Bible &amp; Christianity, many Bibles, and "The God Delusion".  Alright.  Well, you also have some Harry Potter books - some people think that''s just as bad as atheism.  However, some people think that their cats are human.  Moving on...</td>', 'I''ve voted on 62% of the photos so far and this is one of the few photos I''ve seen that actually meets the intent of the challenge, other than just shoe-horning some random portrait.  That being said, good luck with your photo.  So, you''ve got numerous books about the Bible & Christianity, many Bibles, and "The God Delusion".  Alright.  Well, you also have some Harry Potter books - some people think that''s just as bad as atheism.  However, some people think that their cats are human.  Moving on...', '2009-01-25 20:20:18.000000', NULL, 1),
(5218595, 757605, 23053, '<td valign="top">The lens-baby adds a lot of motion and unrest to the photo that is, by name, about melancholy.  I like that symbolism - that you are still and all around you is swirling.  That by being centered, or the center, you do not move by definition.  It''s comforting, but boring.  Hopefully, the forthcoming Spring will provide you with longer days, warmer weather, less snow, and some relief from your melancholic disposition.</td>', 'The lens-baby adds a lot of motion and unrest to the photo that is, by name, about melancholy.  I like that symbolism - that you are still and all around you is swirling.  That by being centered, or the center, you do not move by definition.  It''s comforting, but boring.  Hopefully, the forthcoming Spring will provide you with longer days, warmer weather, less snow, and some relief from your melancholic disposition.', '2009-01-25 20:27:15.000000', NULL, 1),
(5218611, 757080, 81310, '<td valign="top">way over sharpened</td>', 'way over sharpened', '2009-01-25 20:51:42.000000', NULL, 1),
(5218613, 757566, 81310, '<td valign="top">I really like his expression.  However things feel a little too blue in color for me.  Maybe a blue color cast?</td>', 'I really like his expression.  However things feel a little too blue in color for me.  Maybe a blue color cast?', '2009-01-25 20:53:02.000000', NULL, 1),
(5218616, 757466, 80904, '<td valign="top">My guess this one will end up on the front page. Great photo.</td>', 'My guess this one will end up on the front page. Great photo.', '2009-01-25 20:54:49.000000', NULL, 1),
(5218620, 757569, 81310, '<td valign="top">If I don''t view it in full screen I really like it.  With the floor in the bottom uneven it''s very distracting.  Great capture though.</td>', 'If I don''t view it in full screen I really like it.  With the floor in the bottom uneven it''s very distracting.  Great capture though.', '2009-01-25 20:56:39.000000', NULL, 1),
(5218622, 757481, 81310, '<td valign="top">I like his expression.  His skin tones look really off for me though.</td>', 'I like his expression.  His skin tones look really off for me though.', '2009-01-25 20:57:08.000000', NULL, 1),
(5218625, 757332, 81310, '<td valign="top">This seems very over exposed</td>', 'This seems very over exposed', '2009-01-25 20:57:53.000000', NULL, 1),
(5218628, 757481, 80904, '<td valign="top">Man, I hope this one ends on the top 3. It made me laugh out loud and almost snorted soda thru my nose. 10 from me</td>', 'Man, I hope this one ends on the top 3. It made me laugh out loud and almost snorted soda thru my nose. 10 from me', '2009-01-25 20:59:23.000000', NULL, 1),
(5218630, 757659, 81310, '<td valign="top">I really like the idea of this photo, not thrilled with his expression.</td>', 'I really like the idea of this photo, not thrilled with his expression.', '2009-01-25 21:00:56.000000', NULL, 1),
(5218633, 755931, 81310, '<td valign="top">This totally creeped me out.  Way over sharpened.</td>', 'This totally creeped me out.  Way over sharpened.', '2009-01-25 21:02:25.000000', NULL, 1),
(5218634, 755899, 81310, '<td valign="top">out of focus</td>', 'out of focus', '2009-01-25 21:03:06.000000', NULL, 1),
(5218709, 755597, 81310, '<td valign="top">this seems really sharp, the hair is ''crispy''</td>', 'this seems really sharp, the hair is ''crispy''', '2009-01-25 21:36:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5218725, 757506, 81310, '<td valign="top">I like the concept of this photo.  The issue I have is where the light falls.  The vanity is in her face, and her obsession with her looks while applying makeup.  The light falling on her breasts draws the eye away from her eyes.  Has the lighting been different I would have scored higher.</td>', 'I like the concept of this photo.  The issue I have is where the light falls.  The vanity is in her face, and her obsession with her looks while applying makeup.  The light falling on her breasts draws the eye away from her eyes.  Has the lighting been different I would have scored higher.', '2009-01-25 21:40:25.000000', NULL, 1),
(5218741, 757108, 62187, '<td valign="top">The focus is a blurry...OHHHH maybe that''s the idea! I know I''m a little blurry before my first cup of coffee!</td>', 'The focus is a blurry...OHHHH maybe that''s the idea! I know I''m a little blurry before my first cup of coffee!', '2009-01-25 21:45:37.000000', NULL, 1),
(5218750, 757247, 62187, '<td valign="top">My dog hates to have anybody touch her feet. I feel bad when I take her to have her nails trimmed and I always tip the groomer well for their trouble. They always tell me, ''you know, they make trimmers/grinders for this that you can do yourself''. I say ''yes, I know. I have one.'' Ok, the photo: nice silhouette and I''ll bet that puppy has quite the personality!</td>', 'My dog hates to have anybody touch her feet. I feel bad when I take her to have her nails trimmed and I always tip the groomer well for their trouble. They always tell me, ''you know, they make trimmers/grinders for this that you can do yourself''. I say ''yes, I know. I have one.'' Ok, the photo: nice silhouette and I''ll bet that puppy has quite the personality!', '2009-01-25 21:48:44.000000', NULL, 1),
(5218759, 757886, 62187, '<td valign="top">Gosh, it''s like he''s an adult in a baby body AND behind glass. It''s freakin'' me out...certainly a good entry for the challenge.</td>', 'Gosh, it''s like he''s an adult in a baby body AND behind glass. It''s freakin'' me out...certainly a good entry for the challenge.', '2009-01-25 21:51:05.000000', NULL, 1),
(5218765, 757692, 62187, '<td valign="top">I don''t think I could ever bring myself to wear shoes like that. Despite being a little ''busy'', you''ve got some very nice focus on your subject.</td>', 'I don''t think I could ever bring myself to wear shoes like that. Despite being a little ''busy'', you''ve got some very nice focus on your subject.', '2009-01-25 21:53:06.000000', NULL, 1),
(5218769, 756967, 96530, '<td valign="top">Nicely done, I''ve seen these protesters walking the streets of Seattle a couple of times and have never quite been able to compose a shot as well as this.</td>', 'Nicely done, I''ve seen these protesters walking the streets of Seattle a couple of times and have never quite been able to compose a shot as well as this.', '2009-01-25 21:53:41.000000', NULL, 1),
(5218775, 757844, 62187, '<td valign="top">At first I had this at a 6. I must say, I''m glad I came back. It''s an excellent photo: the focus is dead on, it''s a nice conversion, I see no grain (a lot of the photos in this challenge have been grainy to me - especially the B&amp;W ones), the composition is nice. Ok,here''s my bump: 9. Nah, she looks like a ten to me: 10</td>', 'At first I had this at a 6. I must say, I''m glad I came back. It''s an excellent photo: the focus is dead on, it''s a nice conversion, I see no grain (a lot of the photos in this challenge have been grainy to me - especially the B&W ones), the composition is nice. Ok,here''s my bump: 9. Nah, she looks like a ten to me: 10', '2009-01-25 21:55:50.000000', NULL, 1),
(5218777, 757190, 62187, '<td valign="top">No...YOU first!!! Looks cold - the border is good.</td>', 'No...YOU first!!! Looks cold - the border is good.', '2009-01-25 21:56:54.000000', NULL, 1),
(5218781, 757520, 62187, '<td valign="top">Awesome photo but what is their personality? Old fuddy duddie''s? Just kidding. Hmmm? Maybe I should joke around: I think he''s packin'' a gun there. The focus is certainly sharp - very sharp indeed.</td>', 'Awesome photo but what is their personality? Old fuddy duddie''s? Just kidding. Hmmm? Maybe I should joke around: I think he''s packin'' a gun there. The focus is certainly sharp - very sharp indeed.', '2009-01-25 21:59:05.000000', NULL, 1),
(5218785, 756823, 62187, '<td valign="top">But I can''t see the ''Art'' very well. Oh...I see...the man is ''Art''? Like Arthur? No...Well: it looks like a well focused photo in what looks like low lighting.</td>', 'But I can''t see the ''Art'' very well. Oh...I see...the man is ''Art''? Like Arthur? No...Well: it looks like a well focused photo in what looks like low lighting.', '2009-01-25 22:01:09.000000', NULL, 1),
(5218787, 757286, 62187, '<td valign="top">You''ve certainly captured that...</td>', 'You''ve certainly captured that...', '2009-01-25 22:02:19.000000', NULL, 1),
(5218788, 757304, 62187, '<td valign="top">Wow, it''s very, very busy. Busy, but very interesting to look at.</td>', 'Wow, it''s very, very busy. Busy, but very interesting to look at.', '2009-01-25 22:02:49.000000', NULL, 1),
(5218795, 757551, 62187, '<td valign="top">I Googled it: I found Monkeying Around and Monkeyin'' Around. Either way, they look like they could be some Monkey''s for sure!</td>', 'I Googled it: I found Monkeying Around and Monkeyin'' Around. Either way, they look like they could be some Monkey''s for sure!', '2009-01-25 22:11:13.000000', NULL, 1),
(5218796, 757450, 62187, '<td valign="top">I''m getting some strange bright spots that look well...kinda strange...like they don''t belong there but they are.</td>', 'I''m getting some strange bright spots that look well...kinda strange...like they don''t belong there but they are.', '2009-01-25 22:11:18.000000', NULL, 1),
(5218798, 757538, 62187, '<td valign="top">What a bizarre crop. I think it works.</td>', 'What a bizarre crop. I think it works.', '2009-01-25 22:11:53.000000', NULL, 1),
(5218799, 755931, 62187, '<td valign="top">Fun with photoshop. Why not!</td>', 'Fun with photoshop. Why not!', '2009-01-25 22:12:26.000000', NULL, 1),
(5218800, 757584, 62187, '<td valign="top">It''s got a weird candid effect and the focus is very good.</td>', 'It''s got a weird candid effect and the focus is very good.', '2009-01-25 22:12:55.000000', NULL, 1),
(5218802, 757559, 62187, '<td valign="top">Oh I love trying to guess who the people are. I know, I know...it''s...Scalvert! Focus, lighting and composition are great. };&gt;)</td>', 'Oh I love trying to guess who the people are. I know, I know...it''s...Scalvert! Focus, lighting and composition are great. };>)', '2009-01-25 22:15:26.000000', NULL, 1),
(5218807, 755862, 62187, '<td valign="top">It''s a little dark but good job with a backlit subject. The tree he planted is kinda in the way: to me.</td>', 'It''s a little dark but good job with a backlit subject. The tree he planted is kinda in the way: to me.', '2009-01-25 22:17:15.000000', NULL, 1),
(5218810, 756953, 62187, '<td valign="top">Could you possibly add: ''In debt''? I like the edit.</td>', 'Could you possibly add: ''In debt''? I like the edit.', '2009-01-25 22:18:34.000000', NULL, 1),
(5218815, 755961, 62187, '<td valign="top">High on Life? Wow...where can I get some! So, is somebody here planning on going to the Olympics? I''m sure there must be an event he can enter. Oh, and great photo for the challenge by the way!</td>', 'High on Life? Wow...where can I get some! So, is somebody here planning on going to the Olympics? I''m sure there must be an event he can enter. Oh, and great photo for the challenge by the way!', '2009-01-25 22:24:43.000000', NULL, 1),
(5218818, 756956, 62187, '<td valign="top">I''m not a fan of the ''centered'' subject/object but this is working better then most. The conversion is good and I''m not seeing any weird green or yellowish colors that sometimes happen nor is there any grain/noise. I think the focus could be a little sharper. But, ''kind''? Are you sure? Nobody here at DPC is very kind. Ha ha...great capture for the challenge...</td>', 'I''m not a fan of the ''centered'' subject/object but this is working better then most. The conversion is good and I''m not seeing any weird green or yellowish colors that sometimes happen nor is there any grain/noise. I think the focus could be a little sharper. But, ''kind''? Are you sure? Nobody here at DPC is very kind. Ha ha...great capture for the challenge...', '2009-01-25 22:27:15.000000', NULL, 1),
(5218819, 757224, 62187, '<td valign="top">The baby almost looks like a toy - it''s freakin'' me out. The focus seems a little soft - but maybe that was the intention?</td>', 'The baby almost looks like a toy - it''s freakin'' me out. The focus seems a little soft - but maybe that was the intention?', '2009-01-25 22:28:32.000000', NULL, 1),
(5218823, 757602, 62187, '<td valign="top">At first I rated this a 6. On second look, I realized I must have been completely out of my mind that first time. Awesome shot: 10</td>', 'At first I rated this a 6. On second look, I realized I must have been completely out of my mind that first time. Awesome shot: 10', '2009-01-25 22:30:41.000000', NULL, 1),
(5218825, 757474, 62187, '<td valign="top">The low contrast seems very weird. Please don''t be offended but it almost looks...well...like she''s almost...not so well. All in all, it''s a very interesting photo to me.</td>', 'The low contrast seems very weird. Please don''t be offended but it almost looks...well...like she''s almost...not so well. All in all, it''s a very interesting photo to me.', '2009-01-25 22:33:47.000000', NULL, 1),
(5218826, 756876, 62187, '<td valign="top">Very interesting photo but I''m not seeing how it captures an individuals personality.</td>', 'Very interesting photo but I''m not seeing how it captures an individuals personality.', '2009-01-25 22:33:52.000000', NULL, 1),
(5218841, 756448, 62187, '<td valign="top">It will be interesting to see if over time she retains that trait. For now, the main focus seems to be on the hat rather then her face.</td>', 'It will be interesting to see if over time she retains that trait. For now, the main focus seems to be on the hat rather then her face.', '2009-01-25 22:45:10.000000', NULL, 1),
(5218843, 757409, 62187, '<td valign="top">Take my word: it''s not just about being ''Famous''. It''s about being rich and famous! When I grow up, I wanna be...wait...it''s too late! The focus seems a little bit soft - maybe intentional?</td>', 'Take my word: it''s not just about being ''Famous''. It''s about being rich and famous! When I grow up, I wanna be...wait...it''s too late! The focus seems a little bit soft - maybe intentional?', '2009-01-25 22:47:03.000000', NULL, 1),
(5218845, 755553, 62187, '<td valign="top">They look very sad...I don''t know holiday in Tibet. Do they have an unhappy holiday? I''m probably totally off huh?</td>', 'They look very sad...I don''t know holiday in Tibet. Do they have an unhappy holiday? I''m probably totally off huh?', '2009-01-25 22:48:02.000000', NULL, 1),
(5218846, 756799, 62187, '<td valign="top">Excellent focus!</td>', 'Excellent focus!', '2009-01-25 22:48:28.000000', NULL, 1),
