(5219844, 757397, 46177, '<td valign="top">This one got a 10 from me, I expected it to ribbon but still top 10 is great. Congratulations.</td>', 'This one got a 10 from me, I expected it to ribbon but still top 10 is great. Congratulations.', '2009-01-26 10:03:36.000000', NULL, 0),
